mapper.select:
SELECT
t.userid,
u.nickname,
d.name AS dept_name,
t.qxj_type,
SUM(t.total_ts) AS total_days,
COUNT(t.id) AS count
FROM bpm_leave t
LEFT JOIN system_users u ON t.userid = u.id
LEFT JOIN system_dept d ON u.dept_id = d.id

    t.deleted = 0

        AND t.userid = #{userId}


        AND u.dept_id = #{deptId}


        AND t.qxj_type = #{qxjType}


        AND t.qxj_start_date >= #{beginTime}


        AND t.qxj_start_date <= #{endTime}


        AND t.qxj_type = #{qxjType}


GROUP BY t.userid, t.qxj_type, u.nickname, d.name

HAVING SUM(t.total_ts) > 0
ORDER BY t.userid, t.qxj_type

SELECT * FROM bpm_leave t

    t.deleted = 0

        AND t.userid = #{userId}


        AND t.qxj_type = #{qxjType}


        AND t.qxj_start_date >= #{beginTime}


        AND t.qxj_start_date <= #{endTime}


ORDER BY t.qxj_start_date DESC
